// A local encrypted snapshot; key/config must be backed up separately, never inside a webroot.
$o=getopt('',['to:']);try{$c=srn_config();$target=$o['to']??'';if(!$target||file_exists($target))throw new RuntimeException('Kies een nieuwe private map.');$parent=realpath(dirname($target));$root=realpath(dirname(__DIR__,2));if(!$parent||$parent===$root||str_starts_with($parent,$root.'/')||str_starts_with($parent,$c['dir'].'/'))throw new RuntimeException('Backup buiten webroot en datamap vereist.');mkdir($target,0700);$report=srn_tx($c,function(&$s)use($c,$target){$manifest=[];$state=srn_encrypt(json_encode($s,JSON_THROW_ON_ERROR),$c);srn_atomic($target.'/state.bin',$state);$manifest['state.bin']=hash('sha256',$state);mkdir($target.'/files',0700);foreach($s['files']as$id=>$f){$path=$c['dir'].'/files/'.$id.'.bin';if(is_link($path)||!is_file($path))throw new RuntimeException('Bestand ontbreekt.');$raw=(string)file_get_contents($path);srn_atomic($target.'/files/'.$id.'.bin',$raw);$manifest['files/'.$id.'.bin']=hash('sha256',$raw);}srn_atomic($target.'/manifest.json',json_encode(['schema'=>1,'created'=>gmdate('c'),'hashes'=>$manifest],JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT));return ['files'=>count($manifest),'encrypted'=>true,'keyIncluded'=>false];});echo json_encode($report)."\n";}catch(Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}
